package com.allclearwas.domains.seat.service;import java.util.List;import java.util.Map;import org.springframework.data.redis.core.RedisTemplate;import org.springframework.stereotype.Service;import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;import com.allclearwas.domains.seat.implement.SseAsyncSender;import com.allclearwas.domains.seat.implement.SseEmitterManager;import lombok.RequiredArgsConstructor;import lombok.extern.slf4j.Slf4j;@Slf4j@Service@RequiredArgsConstructorpublic class SseSeatService {	private final SseEmitterManager emitterManager;	private final SseAsyncSender asyncSender;	private final RedisTemplate<String, String> redisTemplate;	public SseEmitter subscribe(Long studentId, List<Long> courseIds) {		log.info("SseSeatService subscribe 시작1");		SseEmitter emitter = new SseEmitter(Long.MAX_VALUE);		emitterManager.addEmitter(studentId, emitter, courseIds);		log.info("SseSeatService subscribe 시작2");		for (Long courseId : courseIds) {			log.info("SseSeatService subscribe 시작3");			String remaining = redisTemplate.opsForValue().get("course:" + courseId + ":remaining");			asyncSender.send(emitter, "seat", Map.of(				"courseId", courseId,				"remaining", remaining			));		}		log.info("SseSeatService subscribe 시작4");		emitter.onCompletion(() -> emitterManager.removeEmitter(studentId));		emitter.onTimeout(() -> emitterManager.removeEmitter(studentId));		emitter.onError((e) -> emitterManager.removeEmitter(studentId));		return emitter;	}	public void notifyRemainingChanged(Long courseId, String remaining) {		for (Map.Entry<Long, List<Long>> entry : emitterManager.getSubscribedCourses().entrySet()) {			Long studentId = entry.getKey();			List<Long> subscribed = entry.getValue();			if (subscribed.contains(courseId)) {				SseEmitter emitter = emitterManager.getEmitter(studentId);				if (emitter != null) {					asyncSender.send(emitter, "seat", Map.of(						"courseId", courseId,						"remaining", remaining					));				}			}		}	}}